import { test, expect } from '@playwright/test';

test.describe('Checkout Form - Card Expiry Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should validate card expiry in MM/YY format and display error message', async ({ page }) => {
    // Fill in required fields
    await page.getByLabel('Card Number').fill('4111111111111111');
    await page.getByLabel('Card Holder Name').fill('John Doe');
    await page.getByLabel('Amount').fill('19.99');

    // Attempt to submit with invalid expiry format
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify error message appears
    const errorMessage = page.getByText('Card expiry must be in MM/YY format');
    await expect(errorMessage).toBeVisible();

    // Verify form is still visible
    const formContainer = page.locator('[data-testid="checkout-form"]');
    await expect(formContainer).toBeVisible();

    // Verify error styling is applied
    const expiryInput = page.getByLabel('Card Expiry');
    await expect(expiryInput).toHaveAttribute('data-testid', 'card-expiry-input');
    await expect(expiryInput).toHaveClass(/error/);

    // Clear error and enter valid expiry
    await expiryInput.clear();
    await expiryInput.fill('12/25');

    // Verify error message disappears
    await expect(errorMessage).not.toBeVisible();

    // Verify expiry input no longer has error class
    await expect(expiryInput).not.toHaveClass(/error/);

    // Verify submit button is now enabled
    await expect(submitButton).toBeEnabled();
  });

  test('should allow submission with valid MM/YY expiry and display success message', async ({ page }) => {
    // Fill in required fields
    await page.getByLabel('Card Number').fill('4111111111111111');
    await page.getByLabel('Card Holder Name').fill('Jane Smith');
    await page.getByLabel('Amount').fill('49.99');

    // Enter valid expiry date
    const expiryInput = page.getByLabel('Card Expiry');
    await expiryInput.fill('05/27');

    // Verify expiry input has correct value
    await expect(expiryInput).toHaveValue('05/2025');

    // Click submit button
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByText('Payment successful');
    await expect(successMessage).toBeVisible();

    // Verify user is redirected to order confirmation page
    await expect(page).toHaveURL(/.*\/order-confirmation/);

    // Verify order details are displayed
    const orderId = page.getByText(/Order #\d+/);
    await expect(orderId).toBeVisible();
  });
});
